"""Scenario checks v2: distractors encode misconceptions rather than tone cues."""
CHECKS = {
 'ml-intro': ('想用企鹅测量值预测物种，哪份实验目标描述最完整？', ['按测量值聚类，以组内距离评价物种预测','用测量特征学习物种，在未参与训练的样本上评估','用物种预测测量值，以训练误差评价分类'],1,'这里输入是测量特征，目标是物种；还需要用未参与训练的样本评估预测。聚类距离或反向预测不能代替这项分类任务。'),
 'task-types': ('图片中的“猫”和“室内”可以同时成立，怎样定义这两个输出？', ['把两个词合成一个类别，再让每张图片只选这一类','把两个词编码成数值，再拟合它们的连续数值大小','分别判断两个标签是否成立'],2,'多标签允许同一图片同时具有多个标签。合成单一类别会改变输出定义；数值编码也不会把标签变成连续回归目标。'),
 'train-infer': ('模型已经训练完成，只切换到另一条验证样本，应该更新什么？', ['该样本的预测与解释','用新验证样本重新估计的系数，再刷新本次预测','重新抽取的训练验证划分，再刷新这次验证指标'],0,'探针解释既有模型对另一条样本的输出。重新估计系数或重新划分集合属于另一项实验操作。'),
 'features': ('预测单车总需求cnt时，casual与registered相加恰好等于cnt。应如何处理？', ['保留两列作为输入，在划分完成后统一标准化','排除这两列目标泄漏输入，使用预测时可提前获得的特征','只保留其中一列作为输入，再用验证集选择另一列'],1,'两列包含目标的直接组成信息，预测时不能提前获得。划分和标准化无法消除这种目标泄漏，只删其中一列仍会保留泄漏。'),
 'splits': ('你已根据测试分数选了树深，接下来怎样描述这份测试结果？', ['它已参与超参数选择，只能作为探索证据，应另找独立样本评估','恢复原先树深后，这份测试结果就恢复独立性质','重新打乱原有样本，再将其中一份命名为独立测试'],0,'测试信息已影响选择，撤回参数或给原样本改名都不能消除接触历史。后续结论需要如实标记，并寻找未参与决策的评估。'),
 'preprocess': ('只取训练池25%的样本训练KNN，填补与缩放应在哪些行上拟合？', ['在完整训练池拟合处理器，之后只用25%样本拟合模型','在完整训练池的全部样本上拟合','在本次采用的25%训练样本上拟合处理器'],2,'处理器也是学习过程的一部分，应和模型使用同一实际训练子集。其他训练池样本或验证样本不能提供本次拟合统计。'),
 'linear': ('固定划分后增大Ridge的α，首先可以从模型目标确认哪种变化？', ['优化过程会更重视让验证样本上的残差平方和减小','目标函数会更重视系数惩罚','输入特征的因果贡献会变小，因而更适合部署使用'],1,'α调整训练目标中的系数惩罚权重。它不直接优化验证误差，也不提供因果结论；验证变化仍需要实际计算。'),
 'local-models': ('KNN使用四个缩放后特征。二维图上最近的点不是实际邻居，怎样解释？', ['实际邻居按完整处理空间的距离选取','实际邻居按二维投影选取，只是图中显示顺序不同','先按目标类别筛选近邻'],0,'二维投影丢掉了其他输入的信息。KNN在模型采用的完整处理空间中找邻居，不能先按未知目标筛选邻居。'),
 'trees': ('画面只展示随机森林前5棵树，实际训练了60棵。最终预测用哪些输出？', ['只用展示的5棵树集成，让预测与画面中的树保持一致','从60棵树中选验证分数最高的一棵作为最终模型输出','按已训练模型的集成规则，使用全部60棵树的输出来计算最终预测'],2,'展示子集用于解释，最终预测仍由完整森林的规则计算。选一棵树或只用展示的树会变成不同模型。'),
 'generalize': ('训练误差很低、验证误差偏高，哪项后续操作能提供更有用的证据？', ['补充训练集指标，确认模型拟合充分','核对数据与划分，再固定验证集做受控模型比较','按验证残差剔除较难样本，保持模型后再比较筛选后的误差'],1,'先核对数据质量与集合角色，再保持验证身份比较方案。更多训练指标不能替代泛化评估，按验证难度筛样本会改变评估对象。'),
 'metrics': ('两个回归任务分别预测MPa与L/100km。怎样解释它们的RMSE？', ['分别结合各自单位与基线解释','把两个RMSE直接排序，较小值对应的模型更实用','将目标名称去掉后汇总误差，用平均值比较两种模型'],0,'RMSE带有目标单位，数值大小依赖任务尺度。跨任务汇总前需定义可比的评价方式，不能直接按原始误差排名。'),
 'controlled': ('A与B不仅树深不同，验证样本也变了。当前可以得出哪种结论？', ['把误差差值归因于树深','按验证误差较小者定格，再用它证明树深选择的效果','可并列观察，但需固定评估身份后再归因树深'],2,'同时改变评估群体会混入样本差异。可以保留两次观察；要解释树深的影响，还需相同评估条件的受控对照。'),
 'transformers': ('同一个词出现在两句不同上下文中，注意力主要为其表示引入什么？', ['词在词典中的固定含义，按词频为这一含义加权','当前输入中其他位置的信息','经事实数据库核实的语义，使上下文输出具备来源'],1,'注意力根据输入之间的关系汇集上下文信息。它不是固定词义表或事实核验数据库，权重也不是完整的因果解释。'),
 'transfer': ('给模型补充几个提示示例，与微调的关键区别是什么？', ['提示改变当前输入上下文；微调则通过继续训练更新部分或全部可学习参数','提示更新少量参数，微调仅改变当前会话中的输入','提示替换分词词典，微调替换生成答案后的展示规则'],0,'提示示例属于当前输入上下文；微调涉及继续训练参数。两者都需要评估，不能只根据界面或回答风格判断发生了训练。'),
 'rag': ('文档已更正，但RAG回答仍沿用旧说法。首先应该检查哪个环节？', ['提高生成温度，增加答案多样性','修改提示中的回答长度，让生成器覆盖更广的资料范围','核对入库索引及实际检索到的片段是否更新'],2,'RAG依赖检索到的上下文，应先核对资料入库、索引与实际检索片段。温度或答案长度不能替代检索正确性核验。'),
 'multimodal': ('星球插画和训练后的残差图同时出现，哪些内容能支撑模型误差结论？', ['插画中的目标与场景是否符合这次任务','本次运行计算得到的残差和指标，连同对应的数据条件','插画与残差图中数量接近的点，让两种图案可以相互印证'],1,'误差结论要回到对应运行、样本和计算。插画帮助识别主题，但装饰点不能替代残差或指标。'),
 'agents': ('AI建议减少树深，你已点击采用。怎样才能核验“这次改善了验证表现”？', ['确认建议确已执行，再核对相同数据和评估条件下的前后真实指标','确认建议格式合法，再把模型写出的预期当作改善记录','确认参数数值下降，再把更简单的模型记作验证表现改善'],0,'合法建议、实际执行和效果核验是不同环节。只有执行后的同条件实算支持该判断，才能说这次验证表现改善。'),
 'responsible': ('总体准确率较高，部署到新采集环境前最值得补哪项核验？', ['继续提高原训练集准确率，并用它替代新环境中的检查','复用原验证分数，确认新环境中输入列名称保持相同','检查新环境代表性、分组错误和结果来源'],2,'环境和群体差异可能被总体指标掩盖。列名相同不代表分布相同，原训练或验证成绩不能替代新环境核验。'),
}
